import{_ as a,o as e,c as i,a3 as s}from"./chunks/framework.BNNhFWPR.js";const k=JSON.parse('{"title":"Installing a release","description":"Download the editor and the export runtime for Windows, macOS or Linux.","frontmatter":{"id":"installing","title":"Installing a release","order":1,"description":"Download the editor and the export runtime for Windows, macOS or Linux.","editUrl":"https://github.com/ATMO-Engine/atmo/edit/main/docs/en/getting-started/installing.md"},"headers":[],"relativePath":"getting-started/installing.md","filePath":"en/getting-started/installing.md"}'),n={name:"getting-started/installing.md"};function o(r,t,l,h,d,p){return e(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="installing-a-release" tabindex="-1">Installing a release <a class="header-anchor" href="#installing-a-release" aria-label="Permalink to &quot;Installing a release&quot;">​</a></h1><p>Each version of ATMO is published on the <a href="https://github.com/ATMO-Engine/atmo/releases" target="_blank" rel="noreferrer">releases page</a> as two zip files per system: the editor, and the export runtime used to <a href="/latest/manual/exporting" class="atmo-ref atmo-ref--page" data-preview="Turn a project into a standalone executable, and check that it contains everything it needs.">export games</a>. To build the engine yourself instead, see <a href="/latest/getting-started/building-from-source" class="atmo-ref atmo-ref--page" data-preview="Install the toolchain and build the engine, its tests and the export runtime.">Building from source</a>.</p><h2 id="downloads" tabindex="-1">Downloads <a class="header-anchor" href="#downloads" aria-label="Permalink to &quot;Downloads {#downloads}&quot;">​</a></h2><p><code>&lt;version&gt;</code> is the engine version, such as <code>1.0.0</code>.</p><table tabindex="0"><thead><tr><th>System</th><th>Editor</th><th>Export runtime</th></tr></thead><tbody><tr><td>Windows</td><td><code>atmo_&lt;version&gt;_windows.zip</code></td><td><code>atmo-export_&lt;version&gt;_windows.zip</code></td></tr><tr><td>macOS</td><td><code>atmo_&lt;version&gt;_macos.zip</code></td><td><code>atmo-export_&lt;version&gt;_macos.zip</code></td></tr><tr><td>Linux</td><td><code>atmo_&lt;version&gt;_linux.zip</code></td><td><code>atmo-export_&lt;version&gt;_linux.zip</code></td></tr></tbody></table><p>Each zip contains one program, named like the zip (<code>atmo_1.0.0_windows.exe</code>, <code>atmo_1.0.0_macos.app</code>, <code>atmo_1.0.0_linux</code>, <code>atmo-export_1.0.0_linux</code>…), with the engine&#39;s license and the licenses of the libraries it uses. <code>SHA256SUMS.txt</code> lists the checksum of every zip.</p><p>Use the export runtime of the same version as the editor.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements {#requirements}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>System</th><th>Needs</th></tr></thead><tbody><tr><td>Windows</td><td>64-bit Windows (x64), a graphics driver with Vulkan 1.3</td></tr><tr><td>macOS</td><td>macOS 13 or later on Apple silicon (M1 or later). Intel Macs are not supported</td></tr><tr><td>Linux</td><td>x86-64, glibc 2.39 or later (Ubuntu 24.04, Debian 13, Fedora 40 or later), Vulkan 1.3 GPU</td></tr></tbody></table><h2 id="first-launch" tabindex="-1">First launch <a class="header-anchor" href="#first-launch" aria-label="Permalink to &quot;First launch {#first-launch}&quot;">​</a></h2><p>The programs are not signed, so the system warns about them the first time.</p><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows {#windows}&quot;">​</a></h3><p>Extract the zip and start <code>atmo_&lt;version&gt;_windows.exe</code>. If SmartScreen says that it protected your PC, click <strong>More info</strong>, then <strong>Run anyway</strong>.</p><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS {#macos}&quot;">​</a></h3><p>Extract the zip and move <code>atmo_&lt;version&gt;_macos.app</code> to the Applications folder. macOS blocks programs downloaded from the internet that are not signed, and may say that the app &quot;is damaged&quot;. Remove the download flag once, in a terminal:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -dr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.apple.quarantine</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/atmo_</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">_macos.app</span></span></code></pre></div><p>Do the same for the export runtime before exporting with it:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.apple.quarantine</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> atmo-export_</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">_macos</span></span></code></pre></div><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux {#linux}&quot;">​</a></h3><p>Extract the zip and start <code>./atmo_&lt;version&gt;_linux</code>. The zip keeps the executable permission. If it was lost, run <code>chmod +x atmo_&lt;version&gt;_linux</code> first.</p><p>To start the editor from the application menu with its icon, install the program, the icon and the menu entry for your user:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/bin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/share/applications</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/share/icons/hicolor/256x256/apps</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> atmo_</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">_linux</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/bin/atmo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> atmo.png</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/share/icons/hicolor/256x256/apps/atmo.png</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> atmo.desktop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/share/applications/atmo.desktop</span></span></code></pre></div><p><code>~/.local/bin</code> must be on your <code>PATH</code>. The menu entry starts the program named <code>atmo</code>.</p><h2 id="icons" tabindex="-1">Icons <a class="header-anchor" href="#icons" aria-label="Permalink to &quot;Icons {#icons}&quot;">​</a></h2><p>The editor has the ATMO icon: in the <code>.exe</code> on Windows, in the app bundle on macOS, and on its window on Windows and Linux. Exported games do not have an icon yet.</p>`,25)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
